        "code": "import nanosurf, time, os, json
spm = nanosurf.SPM()
app = spm.application
scan = app.Scan
opmode = app.OperatingMode
# Set scan parameters for 10x10 µm area, 128x128 points
scan.ImageWidth = 10e-6
scan.ImageHeight = 10e-6
scan.Points = 128
scan.Lines = 128
# Desired total scan time per frame ≈51.33 s → time per line ≈0.401 s
scan.Scantime = 0.401
# Gentle scanning mode (assume tapping mode attribute)
try:
    opmode.Mode = 'Tapping'
except Exception as e:
    print('Setting mode failed:', e)
# Function to perform a scan and return saved image path
def run_scan():
    # Start scan (method name may differ)
    try:
        app.start_scan()
    except Exception as e:
        print('start_scan error:', e)
        return None
    # Wait until scan finishes
    while True:
        try:
            if app.is_scan_finished():
                break
        except Exception:
            # fallback: just wait a fixed time
            time.sleep(0.5)
            break
        time.sleep(0.5)
    # Retrieve last image path (method may differ)
    try:
        path = app.get_last_image_path()
    except Exception as e:
        print('get_last_image_path error:', e)
        path = None
    return path
paths = []
for i in range(3):
    p = run_scan()
    if p:
        paths.append(p)
    else:
        print('Scan', i+1, 'failed to produce a path')
    time.sleep(1)
print('Image paths:', json.dumps(paths))"
    }
